[metadata] {"type": "create", "filePath": "/app/src/main/java/ai/unifiedprocess/petclinic/vet/ui/VeterinariansView.java", "content": "package ai.unifiedprocess.petclinic.vet.ui;

import ai.unifiedprocess.petclinic.core.ui.MainLayout;
import ai.unifiedprocess.petclinic.vet.domain.Specialty;
import ai.unifiedprocess.petclinic.vet.domain.Vet;
import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.html.H2;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.data.provider.DataProvider;
import com.vaadin.flow.data.provider.Query;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;

import java.util.stream.Stream;

import static java.util.stream.Collectors.joining;

/**
 * UC-002: View Veterinarians.
 *
 * Route {@code /vets}. Lists the clinic's veterinarians with their specialties
 * in a grid that loads rows as the user scrolls. The surrounding logo and
 * navigation menu are rendered by {@link MainLayout}.
 */
@Route(value = "vets", layout = MainLayout.class)
@PageTitle("Veterinarians")
public class VeterinariansView extends VerticalLayout {

    private final transient VetRepository vetRepository;

    public VeterinariansView(VetRepository vetRepository) {
        this.vetRepository = vetRepository;

        setSizeFull();

        Grid<Vet> grid = new Grid<>(Vet.class, false);
        grid.addColumn(Vet::firstName).setHeader("First name");
        grid.addColumn(Vet::lastName).setHeader("Last name");
        grid.addColumn(VeterinariansView::specialtyNames).setHeader("Specialties");
        grid.setSizeFull();
        grid.setItems(DataProvider.fromCallbacks(this::fetchVets, this::countVets));

        add(new H2("Veterinarians"), grid);
    }

    private Stream<Vet> fetchVets(Query<Vet, Void> query) {
        return vetRepository.findPage(query.getOffset(), query.getLimit());
    }

    private int countVets(Query<Vet, Void> query) {
        return vetRepository.count();
    }

    private static String specialtyNames(Vet vet) {
        if (vet.specialties().isEmpty()) {
            return "none";
        }
        return vet.specialties().stream().map(Specialty::name).collect(joining(", "));
    }
}
