+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.fail;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    /** Column order of the veterinarians grid: first name, last name, specialties. */
+    private static final int SPECIALTIES_COLUMN = 2;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void veterinariansPageOpensWithoutAuthentication() {
+        assertDoesNotThrow(() -> navigate(VeterinariansView.class),
+                "Expected the veterinarians route to open for an anonymous visitor");
+
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsFirstAndLastNameOfEveryVeterinarian() {
+        navigate(VeterinariansView.class);
+        GridTester<Grid<Vet>, Vet> grid = veterinariansGrid();
+
+        assertEquals(6, grid.size(), "Expected one row per veterinarian of the seed data");
+        int douglas = rowOf(grid, "Douglas");
+        assertEquals("Linda", grid.getCellText(douglas, 0));
+        assertEquals("Douglas", grid.getCellText(douglas, 1));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreCommaSeparatedAlphabetically() {
+        navigate(VeterinariansView.class);
+        GridTester<Grid<Vet>, Vet> grid = veterinariansGrid();
+
+        // The seed attaches surgery before dentistry, so only the ORDER BY puts dentistry first.
+        assertEquals("dentistry, surgery", grid.getCellText(rowOf(grid, "Douglas"), SPECIALTIES_COLUMN));
+        assertEquals("radiology", grid.getCellText(rowOf(grid, "Leary"), SPECIALTIES_COLUMN));
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void veterinarianWithoutSpecialtiesShowsNone() {
+        navigate(VeterinariansView.class);
+        GridTester<Grid<Vet>, Vet> grid = veterinariansGrid();
+
+        assertEquals("none", grid.getCellText(rowOf(grid, "Carter"), SPECIALTIES_COLUMN));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridLoadsVeterinariansInChunksUntilAllAreLoaded() {
+        navigate(VeterinariansView.class);
+        Grid<Vet> grid = find(Grid.class).single();
+        // The grid is a callback data provider with no in-memory items, so it is queried
+        // by offset and limit exactly as the scroll asks for rows.
+        @SuppressWarnings("unchecked")
+        DataProvider<Vet, Void> provider = (DataProvider<Vet, Void>) grid.getDataProvider();
+
+        List<Vet> firstChunk = provider.fetch(new Query<>(0, 4, List.of(), null, null)).toList();
+        List<Vet> secondChunk = provider.fetch(new Query<>(4, 4, List.of(), null, null)).toList();
+
+        assertEquals(4, firstChunk.size(), "Expected the first scroll step to fetch only its own chunk");
+        assertEquals(2, secondChunk.size(), "Expected the second scroll step to fetch the remainder");
+        assertEquals(6, Stream.concat(firstChunk.stream(), secondChunk.stream())
+                        .map(Vet::id).distinct().count(),
+                "Expected the chunks to cover every veterinarian exactly once");
+        assertEquals(6, provider.size(new Query<>()), "Expected the grid to know the total number of veterinarians");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void clinicWithoutVeterinariansShowsEmptyGrid() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VeterinariansView.class);
+
+        assertEquals(0, veterinariansGrid().size(), "Expected the grid to render with no rows");
+    }
+
+    private GridTester<Grid<Vet>, Vet> veterinariansGrid() {
+        return test(find(Grid.class).single());
+    }
+
+    private int rowOf(GridTester<Grid<Vet>, Vet> grid, String lastName) {
+        for (int row = 0; row < grid.size(); row++) {
+            if (grid.getRow(row).lastName().equals(lastName)) {
+                return row;
+            }
+        }
+        return fail("Expected a row for veterinarian " + lastName);
+    }
+}
